import { AxisScale } from '@visx/axis';
import { getTicks } from '@visx/scale';
import React from 'react';

import { DivAxisWrapper } from './DivAxisWrapper.js';
import { formatDateTicks } from '../../../functions/format-date-ticks.js';
import { getTickValues } from '../../../functions/format-value.js';
import { getVerticalNumTicks } from '../../../functions/ticks.js';
import { Formatter } from '../../../types/formatter.js';
import {
  TickValueFormatter,
  TickPrimitiveValue,
} from '../../../types/tick-value.js';
import { AxisLeft } from '../AxisLeft.js';
import { axisFontProps } from '../constants.js';
import { getTickLabelPropsForValueAxis } from '../functions/get-tick-label-props.js';

/**
 * @internal
 */
export interface TimeLeftAxisProps {
  scale: AxisScale;
  containerWidth: number;
  containerHeight: number;
  formatter?: Formatter;
  label?: string;
  stroke?: string;
}

const TICK_LABEL_PROPS = getTickLabelPropsForValueAxis('left');

/**
 * @internal
 */
export const TimeLeftAxis = (props: TimeLeftAxisProps) => {
  const { scale, containerHeight, containerWidth, label, stroke } = props;

  const numTicks = getVerticalNumTicks(containerHeight);
  const ticks: TickPrimitiveValue[] = getTicks(scale, numTicks);
  const tickValues = getTickValues(
    ticks,
    formatDateTicks as TickValueFormatter,
  );
  const tickFormat = (_: unknown, index: number) => tickValues[index];

  return (
    <DivAxisWrapper
      divAxisStyle={axisFontProps}
      ticks={tickValues}
      label={label}
    >
      <AxisLeft
        data-testid="time-axis-left"
        scale={scale}
        containerSize={containerHeight}
        width={containerWidth}
        numTicks={numTicks}
        tickValues={ticks}
        tickLabelProps={TICK_LABEL_PROPS}
        tickFormat={tickFormat}
        label={label}
        stroke={stroke}
      />
    </DivAxisWrapper>
  );
};

TimeLeftAxis['displayName'] = 'TimeLeftAxis';
